import i18n from '@dhis2/d2-i18n'
import {
    IconCross16,
    IconFilter16,
    Layer,
    FlyoutMenu,
    MenuItem,
    Popper,
    type MenuItemProps,
} from '@dhis2/ui'
import cx from 'classnames'
import { type FC } from 'react'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import classes from './styles/filter-dropdown-button.module.css'
import { useAppDispatch, useAppSelector } from '@hooks'
import {
    clearFilter,
    getFilter,
    setFilter,
} from '@store/dimensions-selection-slice'
import type { DataSourceFilter } from '@types'

type MenuItemClickHandler = NonNullable<MenuItemProps['onClick']>

export const FilterDropdownButton: FC = () => {
    const filters = useMemo<Record<DataSourceFilter, string>>(
        () => ({
            ORGANISATION_UNIT: i18n.t('Org units'),
            PERIOD: i18n.t('Periods'),
            STATUS: i18n.t('Statuses'),
            DATA_ELEMENT: i18n.t('Data elements'),
            PROGRAM_ATTRIBUTE: i18n.t('Program attributes'),
            PROGRAM_INDICATOR: i18n.t('Program indicators'),
            CATEGORY: i18n.t('Categories'),
            CATEGORY_OPTION_GROUP_SET: i18n.t('Category option group sets'),
        }),
        []
    )
    const buttonWrapRef = useRef<HTMLDivElement | null>(null)
    const dispatch = useAppDispatch()
    const activeFilter = useAppSelector(getFilter)
    const activeFilterLabel = useMemo(
        () => (activeFilter ? filters[activeFilter] : undefined),
        [filters, activeFilter]
    )
    const [isOpen, setIsOpen] = useState(false)
    const toggleIsOpen = useCallback(() => {
        setIsOpen((curr) => !curr)
    }, [])
    const setActiveFilter = useCallback<MenuItemClickHandler>(
        ({ value }, event) => {
            event.stopPropagation()
            if (!value) {
                throw new Error('No value set on menu item')
            }
            dispatch(setFilter(value as DataSourceFilter))
            toggleIsOpen()
        },
        [dispatch, toggleIsOpen]
    )
    const clearActiveFilter = useCallback(() => {
        dispatch(clearFilter())
    }, [dispatch])

    useEffect(() => {
        const handleEscape = (event: KeyboardEvent) => {
            if (event.key === 'Escape' && isOpen) {
                setIsOpen(false)
            }
        }

        if (isOpen) {
            document.addEventListener('keydown', handleEscape)
        }

        return () => {
            document.removeEventListener('keydown', handleEscape)
        }
    }, [isOpen])

    return (
        <>
            <div
                className={cx(classes.buttonWrap, {
                    [classes.withBoxShadow]: activeFilter,
                })}
                data-test="filter-dropdown-button-wrap"
                ref={buttonWrapRef}
            >
                <button
                    className={cx(classes.filterButton, {
                        [classes.withSelection]: activeFilter,
                    })}
                    data-test="filter-dropdown-button"
                    onClick={toggleIsOpen}
                >
                    <IconFilter16 />
                    {activeFilterLabel ?? i18n.t('Filter')}
                </button>
                {activeFilter && (
                    <button
                        className={classes.filterClearButton}
                        data-test="filter-clear-button"
                        onClick={clearActiveFilter}
                    >
                        <IconCross16 />
                    </button>
                )}
            </div>
            {isOpen && (
                <Layer
                    onBackdropClick={toggleIsOpen}
                    dataTest="filter-dropdown-backdrop"
                >
                    <Popper reference={buttonWrapRef} placement="bottom-end">
                        <FlyoutMenu dense dataTest="filter-dropdown-menu">
                            {Object.entries(filters).map(([key, label]) => (
                                <MenuItem
                                    label={label}
                                    value={key}
                                    key={key}
                                    onClick={setActiveFilter}
                                    dataTest={`filter-menu-item-${key}`}
                                    active={key === activeFilter}
                                />
                            ))}
                        </FlyoutMenu>
                    </Popper>
                </Layer>
            )}
        </>
    )
}
